/**
 * Given a starting number of coloring books, a number of books given away, and a number of books bought,
 * return the total number of coloring books.
 *
 * @param {number} initialBooks - The initial number of coloring books.
 * @param {number} booksGivenAway - The number of coloring books given away.
 * @param {number} booksBought - The number of coloring books bought.
 * @returns {number} The total number of coloring books.
 */
function calculateTotalColoringBooks(initialBooks, booksGivenAway, booksBought) {
    // First, calculate the number of coloring books left after giving some away.
    let remainingBooks = initialBooks - booksGivenAway;

    // Then, add the number of coloring books bought to the remaining books.
    let totalBooks = remainingBooks + booksBought;

    // Return the total number of coloring books.
    return totalBooks;
}

